"""Named no-collapse and source-closure failures; read-only pure diagnostics."""
import unittest
from audit import *
from jsonschema.exceptions import ValidationError

class CoherenceGuards(unittest.TestCase):
 @classmethod
 def setUpClass(cls):cls.original=snapshot()
 def setUp(self):self.value=copy.deepcopy(self.original)
 def reject(self):
  with self.assertRaises((ValueError,ValidationError,KeyError,StopIteration)):assess(self.value)
 def node(self):return next(r for r in self.value['records'].values() if r['kind']=='ontology-node')
 def edge(self):return next(r for r in self.value['records'].values() if r['kind']=='ontology-edge')
 def intent(self):return next(iter(self.value['intents'].values()))
 def test_all_selected_original_joins(self):self.assertEqual(assess(self.value)['counts']['carriers'],220)
 def test_missing_authority_axis(self):self.value['actual_effects'].pop('source_semantic_admission');self.reject()
 def test_definition_selector_mismatch(self):next(iter(self.value['definition_witnesses'].values()))['reference']['selector_sha256']='0'*64;self.reject()
 def test_native_node_definition_bridge_changed(self):self.value['semantic'][0]['complete_resulting_semantic_state']['semantic_definition_refs'][0]['selector_sha256']='0'*64;self.reject()
 def test_missing_import(self):self.value['imports'].pop();self.reject()
 def test_duplicate_import(self):self.value['imports'][0]=copy.deepcopy(self.value['imports'][1]);self.reject()
 def test_missing_adoption(self):self.value['adoptions'].pop();self.reject()
 def test_missing_source_disposition(self):self.value['dispositions'].pop();self.reject()
 def test_missing_blocked_revision(self):self.value['dispositions']=[r for r in self.value['dispositions'] if r['disposition']!='block'];self.reject()
 def test_current_revision_substitution(self):next(r for r in self.value['dispositions'] if r['disposition']=='block')['disposition']='reference';self.reject()
 def test_missing_exclusion(self):self.value['excluded_packages'].pop();self.reject()
 def test_deferred_epoch_drop(self):self.value['deferred_source_epoch']={};self.reject()
 def test_outside_question_drop(self):self.value['outside_references']={};self.reject()
 def test_metadata_admission_collapsed_into_adoption(self):self.value['imports'][0]['requested_axes']['ontology_representation_adoption']=True;self.reject()
 def test_adoption_collapsed_into_metadata_admission(self):self.value['adoptions'][0]['requested_axes']['metadata_carrier_admission']=True;self.reject()
 def test_admitted_fixture_owner(self):self.value['imports'][0]['scope']['fixture_owner_is_final_owner']=True;self.reject()
 def test_actual_owner_outcome_inferred(self):self.value['actual_owner_outcome']='admitted';self.reject()
 def test_canonical_adoption_inferred(self):self.value['actual_effects']['ontology_representation_adoption']=True;self.reject()
 def test_original_source_meaning_admitted(self):self.value['imports'][0]['scope']['source_semantic_admission']=True;self.reject()
 def test_domain_conformance_inferred(self):self.value['imports'][0]['scope']['domain_instance_conformance']=True;self.reject()
 def test_global_relation_grant(self):self.value['adoptions'][0]['requested_axes']['global_relation_creation']=True;self.reject()
 def test_current_owner_authority_inferred(self):self.value['adoptions'][0]['current_owner_authority_verified']=True;self.reject()
 def test_final_assembly_obligation_dropped(self):self.value['final_assembly_obligations'].pop();self.reject()
 def test_key_export(self):self.value['archive_flags']['private_key_included']=True;self.reject()
 def test_memory_export(self):self.value['archive_flags']['Session_memory_included']=True;self.reject()
 def test_archive_adoption(self):self.value['archive_flags']['ontology_admission']=True;self.reject()
 def test_missing_semantic_event(self):self.value['semantic'].pop();self.reject()
 def test_governance_cursor_collapsed(self):self.value['governance'][0]['governance_cursor']=88;self.reject()
 def test_governance_semantic_digest_mismatch(self):self.value['governance'][0]['semantic_ref']['semantic_event_digest']='0'*64;self.reject()
 def test_nested_governance_tuple_mismatch(self):self.value['governance'][0]['complete_resulting_governance_state']['semantic_ref']['semantic_event_digest']='0'*64;self.reject()
 def test_positive_evidence_confidence(self):self.value['governance'][0]['complete_resulting_governance_state']['evidence_confidence']['level']='high';self.reject()
 def test_commitment_confidence_raised(self):self.value['governance'][0]['complete_resulting_governance_state']['commitment_confidence']['level']='high';self.reject()
 def test_maturity_admitted(self):self.value['governance'][0]['complete_resulting_governance_state']['candidate_or_maturity_status']='admitted';self.reject()
 def test_challenge_owner_gate_removed(self):self.value['governance'][0]['complete_resulting_governance_state']['challenge_contract']['resolution_gate']='automatic';self.reject()
 def test_node_label_as_Product_endpoint(self):self.node()['payload']['represented_subject']['kind']='product';self.reject()
 def test_represented_revision_alias(self):self.node()['payload']['represented_subject']['version_ref']='product:cyberalchemy@current';self.reject()
 def test_represented_digest_mismatch(self):self.node()['payload']['represented_subject']['digest']='0'*64;self.reject()
 def test_rich_node_governance_event_mismatch(self):self.node()['payload']['governance_binding']['governance_event_refs']=['wrong'];self.reject()
 def test_projection_as_replay_source(self):self.node()['payload']['replay_source']=True;self.reject()
 def test_missing_local_endpoint(self):self.edge()['payload']['source_node_ref']='missing';self.reject()
 def test_local_as_global_edge(self):self.edge()['payload']['edge_mode']='global-typed-relation';self.reject()
 def test_global_binding_invented(self):self.edge()['payload']['global_typed_relation_binding']={'relation_kind_ref':'relation.uses'};self.reject()
 def test_source_endpoint_version_changed(self):self.edge()['payload']['closed_qualifiers']['source_node_version_ref']='source:current';self.reject()
 def test_symmetric_direction_erased(self):next(r for r in self.value['records'].values() if r['kind']=='ontology-edge' and r['payload']['direction']=='symmetric')['payload']['direction']='directed';self.reject()
 def test_unclosed_local_predicate(self):self.edge()['payload']['relation_type_ref']='legacy-product-local-predicate:invented/v1-candidate';self.reject()
 def test_predecessor_governance_digest_changed(self):self.intent()['predecessor_governance_tuple']['event_digest']='0'*64;self.reject()
 def test_old_candidate_event_relabeled(self):self.intent()['consequence_rule']['old_candidate_event_relabeling_allowed']=True;self.reject()
 def test_adoption_private_source_meaning(self):self.intent()['consequence_rule']['source_meaning_admitted']=True;self.reject()
 def test_adoption_owner_core_not_required(self):self.intent()['consequence_rule']['provenance_requires_actual_owner_Decision_binding']=False;self.reject()
 def test_adoption_permanent_runtime_granted(self):self.intent()['permanent_runtime_installation_authorized']=True;self.reject()
 def test_unknown_record_field(self):self.node()['unknown_semantic_grant']=True;self.reject()
 def test_adoption_archive_digest_changed(self):self.intent()['archive_binding']['sha256']='0'*64;self.reject()
 def test_duplicate_json_field(self):
  with self.assertRaises(ValueError):parse(b'{"owner":null,"owner":"fixture"}')
 def test_nonfinite_json(self):
  with self.assertRaises(ValueError):parse(b'{"confidence":NaN}')

if __name__=='__main__':unittest.main()
